#!/bin/bash
# Build the vendored non-ZIP engine: liblzma (from XZ Utils) + libarchive.
#
# Preconditions (audited research clones, git-ignored, never committed):
#   research/xz         checked out at v5.8.4 (d3e650e63c110e830fd5391e7f8b45df0b91d3da)
#   research/libarchive checked out at 432ab464725aa99c53de7572979bd9bbbf382ed1
#
# Everything is pinned to the Apple toolchain and CLT SDK:
#   zlib  /Library/Developer/CommandLineTools/SDKs/MacOSX.sdk/usr/lib/libz.tbd
#   bzip2 .../libbz2.tbd          iconv .../libiconv.tbd
#   lzma  our own static build of XZ Utils (0BSD) — the SDK ships no lzma.h.
#   LIBB2/LZ4/ZSTD/LZO/OpenSSL/mbedTLS/Nettle/XML/PCRE are all OFF so CMake
#   never picks up anything from /opt/homebrew.
#
# Outputs (git-ignored, regenerated by this script):
#   vendor/liblzma.xcframework      vendor/libarchive.xcframework
#   vendor/manifest.txt             SHAs and sizes for the ledger
set -euo pipefail
cd "$(dirname "$0")/../.."

REPO=$(pwd)
XZ_DIR=$REPO/research/xz
LA_DIR=$REPO/research/libarchive
XZ_PREFIX=$REPO/research/xz-prefix
LA_PREFIX=$REPO/research/libarchive-prefix
SDK=/Library/Developer/CommandLineTools/SDKs/MacOSX.sdk
: "${CMAKE:=cmake}"

die() { echo "build-vendor: $*" >&2; exit 1; }

[ -f "$XZ_DIR/COPYING" ] || die "research/xz missing (clone tukaani-project/xz, checkout v5.8.4)"
[ -f "$LA_DIR/COPYING" ] || die "research/libarchive missing (clone libarchive/libarchive, checkout 432ab46)"
[ -d "$SDK" ] || die "CLT SDK not found at $SDK"
command -v "$CMAKE" >/dev/null || die "cmake not found"

echo "== [1/3] liblzma (XZ Utils, static) =="
"$CMAKE" -S "$XZ_DIR" -B "$XZ_DIR/build-vendor" \
  -DCMAKE_BUILD_TYPE=Release -DBUILD_SHARED_LIBS=OFF \
  -DXZ_TOOL_XZ=OFF -DXZ_TOOL_XZDEC=OFF -DXZ_TOOL_LZMADEC=OFF \
  -DXZ_TOOL_LZMAINFO=OFF -DXZ_TOOL_SYMLINKS=OFF -DXZ_TOOL_SYMLINKS_LZMA=OFF \
  -DXZ_TOOL_SCRIPTS=OFF \
  -DCMAKE_OSX_ARCHITECTURES=arm64 -DCMAKE_OSX_DEPLOYMENT_TARGET=14.0 \
  -DCMAKE_INSTALL_PREFIX="$XZ_PREFIX" -DCMAKE_INSTALL_LIBDIR=lib >/dev/null
"$CMAKE" --build "$XZ_DIR/build-vendor" --target install >/dev/null

echo "== [2/3] libarchive (static, deps pinned to SDK + own liblzma) =="
"$CMAKE" -S "$LA_DIR" -B "$LA_DIR/build-vendor" \
  -DCMAKE_BUILD_TYPE=Release -DBUILD_SHARED_LIBS=OFF \
  -DENABLE_MBEDTLS=OFF -DENABLE_NETTLE=OFF -DENABLE_OPENSSL=OFF \
  -DENABLE_LIBB2=OFF -DENABLE_LZ4=OFF -DENABLE_LZO=OFF -DENABLE_ZSTD=OFF \
  -DENABLE_LIBXML2=OFF -DENABLE_BSDXML=OFF -DENABLE_EXPAT=OFF \
  -DENABLE_WIN32_XMLLITE=OFF -DENABLE_PCREPOSIX=OFF -DENABLE_PCRE2POSIX=OFF \
  -DENABLE_CNG=OFF \
  -DENABLE_TAR=OFF -DENABLE_CPIO=OFF -DENABLE_CAT=OFF -DENABLE_UNZIP=OFF \
  -DENABLE_TEST=OFF \
  -DENABLE_LZMA=ON -DLIBLZMA_INCLUDE_DIR="$XZ_PREFIX/include" \
  -DLIBLZMA_LIBRARY="$XZ_PREFIX/lib/liblzma.a" \
  -DENABLE_ZLIB=ON -DZLIB_INCLUDE_DIR="$SDK/usr/include" \
  -DZLIB_LIBRARY_RELEASE="$SDK/usr/lib/libz.tbd" \
  -DENABLE_BZip2=ON -DBZIP2_INCLUDE_DIR="$SDK/usr/include" \
  -DBZIP2_LIBRARY_RELEASE="$SDK/usr/lib/libbz2.tbd" \
  -DCMAKE_OSX_ARCHITECTURES=arm64 -DCMAKE_OSX_DEPLOYMENT_TARGET=14.0 \
  -DCMAKE_INSTALL_PREFIX="$LA_PREFIX" >/dev/null
"$CMAKE" --build "$LA_DIR/build-vendor" --target archive_static install >/dev/null

# Refuse a Homebrew-tainted configuration before we ship it. Build-tool
# paths (cmake/git/pkg-config executables) are fine; linked libraries and
# include dirs are not.
if grep -E "(LIBRARY|INCLUDE)[A-Z_]*:.*=/opt/homebrew" "$LA_DIR/build-vendor/CMakeCache.txt"; then
  die "CMakeCache links a /opt/homebrew library or header — dependency pinning failed"
fi

echo "== [3/3] XCFrameworks =="
rm -rf vendor/liblzma.xcframework vendor/libarchive.xcframework
mkdir -p vendor/tmp/lzma vendor/tmp/libarchive
cp "$XZ_PREFIX/lib/liblzma.a" vendor/tmp/lzma/
mkdir -p vendor/headers/lzma
cp -R "$XZ_PREFIX/include/lzma" vendor/headers/lzma/
cp "$XZ_PREFIX/include/lzma.h" vendor/headers/lzma/
cp "$LA_PREFIX/lib/libarchive.a" vendor/tmp/libarchive/
cp "$LA_PREFIX/include/archive.h" "$LA_PREFIX/include/archive_entry.h" vendor/headers/

xcodebuild -create-xcframework \
  -library vendor/tmp/lzma/liblzma.a -headers vendor/headers/lzma \
  -output vendor/liblzma.xcframework >/dev/null
xcodebuild -create-xcframework \
  -library vendor/tmp/libarchive/libarchive.a -headers vendor/headers \
  -output vendor/libarchive.xcframework >/dev/null
rm -rf vendor/tmp

{
  echo "built: $(date -u +%Y-%m-%dT%H:%M:%SZ)"
  echo "xz v5.8.4 d3e650e63c110e830fd5391e7f8b45df0b91d3da"
  echo "libarchive 432ab464725aa99c53de7572979bd9bbbf382ed1"
  for f in vendor/liblzma.xcframework/macos-arm64/liblzma.a \
           vendor/libarchive.xcframework/macos-arm64/libarchive.a; do
    echo "$(shasum -a 256 "$f")"
  done
  echo "codecs enabled: zlib+bzip2+liblzma only (see scripts/vendor/build-vendor.sh)"
} > vendor/manifest.txt

echo "done:"
cat vendor/manifest.txt
